package org.bytefred.ktoy.core

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * Verifies ktoy's C compiler (compileSource) against the Python reference
 * (pytoy). For every embedded C example (see CExamples.kt, generated by
 * scripts/gen_c_examples.py):
 *
 *   1. compileSource(cSource, name) must equal pytoy's golden .toys byte-for-byte.
 *   2. The compiled program, assembled and run to STOP, must leave ACC equal to
 *      the `// expect: N` value declared in the C source.
 *
 * A failure of (1) is a real compiler divergence from pytoy; a failure of (2)
 * (when (1) passed) points at the assemble/run harness, not the compiler.
 */
class CCompilerTest {

    private val SAFETY_CAP = 2_000_000
    private val EXPECT = Regex("""//\s*expect:\s*(\d+)""", RegexOption.IGNORE_CASE)

    /** Run a machine to completion (or the safety cap). */
    private fun runToStop(machine: Machine, name: String) {
        var iterations = 0
        while (machine.step()) {
            iterations += 1
            assertTrue(
                iterations < SAFETY_CAP,
                "'$name' did not stop within $SAFETY_CAP iterations",
            )
        }
    }

    @Test
    fun ktoyCompilerMatchesPytoyByteForByte() {
        for (ex in C_EXAMPLES) {
            val got = compileSource(ex.cSource, ex.name)
            assertEquals(
                ex.expectedToys, got,
                "'${ex.name}': ktoy compileSource output diverges from pytoy golden",
            )
        }
    }

    @Test
    fun compiledProgramsYieldExpectedAcc() {
        for (ex in C_EXAMPLES) {
            val match = assertNotNull(
                EXPECT.find(ex.cSource),
                "'${ex.name}': no '// expect: N' marker in C source",
            )
            val expectedAcc = match.groupValues[1].toInt()

            // Compile with ktoy (already proven byte-identical to pytoy by the
            // other test), then assemble + run the result.
            val asm = compileSource(ex.cSource, ex.name)
            val result = assemble(asm)
            assertTrue(
                result.errors.isEmpty(),
                "'${ex.name}': assembling compiled output failed: " +
                    result.errors.joinToString("\n"),
            )

            val machine = Machine(result.mem, result.dataAddrs)
            runToStop(machine, ex.name)

            assertEquals(
                expectedAcc, machine.acc,
                "'${ex.name}': final ACC mismatch vs '// expect:'",
            )
        }
    }
}
